head.script:
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.data1 = [{
            "col1": "a",
            "col2": "1000"
        },
        {
            "col1": "a",
            "col2": "1000"
        },
        {
            "col1": "b",
            "col2": "b"
        },
        {
            "col1": "c",
            "col2": "3000"
        },
        {
            "col1": "d",
            "col2": "4000"
        }
    ];
    window.data2 = [{
            "col1": "a",
            "col2": "100"
        },
        {
            "col1": "b",
            "col2": "200"
        },
        {
            "col1": "c",
            "col2": "300"
        },
        {
            "col1": "d",
            "col2": "400"
        }
    ];
    dataList1.setJSON(data1);
    dataList2.setJSON(data2);
    window.mergeInfo = {}
    mergeInfo.rowIndex = 0;
    mergeInfo.colIndex = 0;
    mergeInfo.rowSpan = 2;
    mergeInfo.colSpan = 2;
    gridView1.mergeCell(mergeInfo);
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

